from pathlib import Path
import sys,unittest,copy,json,hashlib
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'tools'))
from validate import load,check,errors,examples,ROOT
from reference_rules import critical,bundle_unique,archive,access,delta_bindings,transfer_consistency,activate_transfer
NOW='2026-09-19T12:00:00Z'
class Contracts(unittest.TestCase):
    def setUp(self):
        self.m=load('examples/memory-record.json');self.p=load('examples/consent-policy.json');self.q=load('examples/access-request.json');self.lp=load('examples/lifecycle-policy.json')
    def invalid(self,s,o):self.assertTrue(errors('schemas/'+s+'.schema.json',o))
    def test_examples(self):self.assertGreaterEqual(len(examples()),18)
    def test_original_state(self):check('upstream/aiap-state-schema-v0.1/aiap-state.schema.json',load('upstream/aiap-state-schema-v0.1/example.aiap-state.json'))
    def test_new_state_old_structure_accepts_but_not_security(self):check('upstream/aiap-state-schema-v0.1/aiap-state.schema.json',load('examples/state-profile.json'))
    def test_old_state_not_new_profile(self):self.invalid('state-profile',load('upstream/aiap-state-schema-v0.1/example.aiap-state.json'))
    def test_missing_scope(self):del self.m['scope'];self.invalid('memory-record',self.m)
    def test_missing_policy(self):del self.m['scope']['policy_ref'];self.invalid('memory-record',self.m)
    def test_missing_source_ref(self):del self.m['source']['source_ref'];self.invalid('memory-record',self.m)
    def test_invalid_date(self):self.m['created_at']='yesterday';self.invalid('memory-record',self.m)
    def test_invalid_level(self):self.m['level']='work';self.invalid('memory-record',self.m)
    def test_confidence_range(self):self.m['confidence']=2;self.invalid('memory-record',self.m)
    def test_legacy_archived_must_migrate(self):self.m['status']='archived';self.invalid('memory-record',self.m)
    def test_deleted_separate_tombstone(self):self.m['status']='deleted';self.invalid('memory-record',self.m)
    def test_m3_active_usable(self):self.m['level']='M3';check('schemas/memory-record.schema.json',self.m)
    def test_tombstone_cannot_hold_content(self):x=load('examples/tombstone.json');x['content']='private';self.invalid('tombstone',x)
    def test_bundle_nonempty(self):x=load('examples/bundle-manifest.json');x['cores']=[];self.invalid('bundle-manifest',x)
    def test_duplicate_avatar_different_record(self):x=load('examples/bundle-manifest.json');x['cores'][1]['avatar_id']=x['cores'][0]['avatar_id'];self.assertFalse(bundle_unique(x))
    def test_known_extension(self):self.assertTrue(critical([{'namespace':'x-aiap-core-profile','version':'0.1-draft','critical':True}]))
    def test_unknown_critical(self):self.assertFalse(critical([{'namespace':'unknown','version':'1','critical':True}]))
    def test_missing_critical(self):self.assertFalse(critical([]))
    def test_optional_unknown_preserved(self):x=load('examples/profile-manifest.json')['required_extensions'];x.append({'namespace':'x-demo','version':'1','critical':False});self.assertTrue(critical(x))
    def test_private_work_allowed(self):self.assertTrue(access(self.m,self.q,self.p,NOW))
    def test_life_not_work(self):self.assertFalse(access(load('examples/memory-life.json'),self.q,self.p,NOW))
    def test_organization_not_personal(self):self.assertFalse(access(load('examples/memory-organization.json'),self.q,self.p,NOW))
    def test_other_member_denied(self):self.q['authenticated_subject_ref']='aiap-id:demo-b';self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_other_organization_denied(self):self.q['space_refs']=['space:org-b'];self.assertFalse(access(load('examples/memory-organization.json'),self.q,self.p,NOW))
    def test_export_not_read(self):self.q['action']='export';self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_admin_not_read(self):self.p['rules'][0]['actions']=['admin'];self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_deny_wins(self):r=copy.deepcopy(self.p['rules'][0]);r['effect']='deny';self.p['rules'].append(r);self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_revocation(self):self.assertFalse(access(self.m,self.q,self.p,NOW,revoked=True))
    def test_tombstone_blocks_old_copy(self):self.assertFalse(access(self.m,self.q,self.p,NOW,deleted=True))
    def test_expired(self):self.assertFalse(access(self.m,self.q,self.p,'2026-09-21T00:00:00Z'))
    def test_wrong_purpose(self):self.q['purpose']='marketing';self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_wrong_runtime(self):self.q['runtime_ref']='runtime:other';self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_wrong_session(self):self.q['session_ref']='session:other';self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_old_policy(self):self.p['revision']=2;self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_embedding_not_implicitly_authorized(self):self.q['processor_refs']=['ollama:demo'];self.assertFalse(access(self.m,self.q,self.p,NOW))
    def test_pinned_stays(self):self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'protected')
    def test_stable_stays(self):self.m['retention']={'pinned':False,'decay_exempt':False};self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'protected')
    def ordinary(self):
        self.m['retention']={'pinned':False,'decay_exempt':False};self.m['lifecycle']['stable_preference']=False
    def test_unused_archives(self):self.ordinary();self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'archive-to-M3')
    def test_recent_stays(self):self.ordinary();self.assertEqual(archive(self.m,self.lp,NOW),'keep')
    def test_recurring_protected(self):self.ordinary();self.m['lifecycle']['recurrence_ref']='annual';self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'protected')
    def test_active_task_protected(self):self.ordinary();self.m['lifecycle']['active_task_refs']=['task:1'];self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'protected')
    def test_expected_use_protected(self):self.ordinary();self.m['lifecycle']['expected_next_use']='2027-09-21T00:00:00Z';self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'protected')
    def test_background_recall_not_use(self):self.ordinary();self.m['recall_count']=999999;self.assertEqual(archive(self.m,self.lp,'2027-09-20T00:00:00Z'),'archive-to-M3')
    def test_bad_future_clock(self):self.m['lifecycle']['last_used_at']='2099-01-01T00:00:00Z';self.assertEqual(archive(self.m,self.lp,NOW),'E_TIME')
    def test_cannot_disable_pinned_guard(self):self.lp['protect_pinned']=False;self.invalid('lifecycle-policy',self.lp)
    def test_cannot_enable_auto_delete(self):self.lp['never_auto_delete']=False;self.invalid('lifecycle-policy',self.lp)
    def delta(self):return load('examples/state-delta.json')
    def test_delta_valid_binding(self):self.assertTrue(delta_bindings(self.delta(),{self.m['memory_id']:self.m}))
    def test_delta_stale(self):x=self.delta();x['bindings'][0]['base_revision']=2;self.assertFalse(delta_bindings(x,{self.m['memory_id']:self.m}))
    def test_delta_scope_tamper(self):x=self.delta();x['bindings'][0]['scope']['space_ref']='space:life';self.assertFalse(delta_bindings(x,{self.m['memory_id']:self.m}))
    def test_delta_missing_binding(self):x=self.delta();x['bindings']=[];self.assertFalse(delta_bindings(x,{self.m['memory_id']:self.m}))
    def test_delta_cannot_self_accept(self):x=self.delta();x['delta']['status']='accepted';self.invalid('state-delta',x)
    def test_delta_inferred_not_fact(self):x=self.delta();x['delta']['changes'][0]['candidate']['source']['source_type']='inferred';self.assertFalse(delta_bindings(x,{self.m['memory_id']:self.m}))
    def test_delta_avatar_mismatch(self):x=self.delta();x['delta']['avatar_id']='avatar:other';self.assertFalse(delta_bindings(x,{self.m['memory_id']:self.m}))
    def transfer(self):return load('examples/scoped-transfer-certificate.json'),load('examples/transfer-manifest.json'),(ROOT/'examples/transfer-manifest.json').read_bytes()
    def test_transfer_consistent_structure(self):c,m,b=self.transfer();self.assertTrue(transfer_consistency(c,m,b,NOW,'runtime:destination-demo'))
    def test_transfer_tampered_bytes(self):c,m,b=self.transfer();self.assertFalse(transfer_consistency(c,m,b+b' ',NOW,'runtime:destination-demo'))
    def test_transfer_wrong_destination(self):c,m,b=self.transfer();self.assertFalse(transfer_consistency(c,m,b,NOW,'runtime:attacker'))
    def test_transfer_expired(self):c,m,b=self.transfer();self.assertFalse(transfer_consistency(c,m,b,'2026-09-21T00:00:00Z','runtime:destination-demo'))
    def test_transfer_wrong_scope(self):c,m,b=self.transfer();c['payload']['space_refs']=['space:life'];self.assertFalse(transfer_consistency(c,m,b,NOW,'runtime:destination-demo'))
    def test_transfer_missing_nonce(self):c,_,_=self.transfer();del c['payload']['nonce'];self.invalid('scoped-transfer-certificate',c)
    def test_fixture_never_activates(self):self.assertEqual(activate_transfer(*self.transfer()),'E_CRYPTO_PROFILE_UNSUPPORTED')
if __name__=='__main__':unittest.main()
